'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const courses=[
{id:'html',title:'HTML Foundations',symbol:'5',level:'Beginner',category:'Web development',color:'#e96d43',bg:'#fff0e9',desc:'Structure accessible, meaningful web pages with semantic HTML.',duration:'1.5 hours',source:'https://www.w3schools.com/html/',sourceName:'W3Schools HTML',lessons:[
{title:'What is HTML?',time:8,intro:'HTML (HyperText Markup Language) describes the structure and meaning of content on a web page. A browser reads HTML and turns its elements into the page you see.',goals:['Explain what HTML does','Recognize elements, tags, and attributes','Create a valid starter document'],sections:[['Elements and tags','Most HTML elements use an opening tag, content, and a closing tag. For example, <p>Hello</p> is a paragraph element. Some elements, such as <img>, are void elements and do not wrap text.'],['A first page','The doctype tells the browser to use modern HTML. The html element contains the page; head stores metadata; body contains visible content.'],['Attributes','Attributes add information to elements. For example, href tells a link where to go, while lang identifies the page language.']],code:'<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <title>My first page</title>\n</head>\n<body>\n  <h1>Hello, world!</h1>\n  <p>I made my first web page.</p>\n</body>\n</html>',output:'A page showing a large “Hello, world!” heading and a paragraph.',tip:'Use one meaningful main heading and keep document structure logical. HTML is for meaning and structure; CSS controls presentation.',quiz:{q:'What is HTML mainly used for?',opts:['Structuring web content','Styling colors only','Storing database records'],correct:0,why:'HTML defines the structure and meaning of web content.'}},
{title:'Headings, paragraphs & text',time:10,intro:'Headings organize information into a hierarchy. Paragraphs group sentences. Using the correct element makes content easier to read, navigate, and understand with assistive technology.',goals:['Use h1–h6 in a logical hierarchy','Write paragraphs and emphasis','Avoid choosing elements only for their default size'],sections:[['Headings','Use h1 for the page’s main topic, then h2 for major sections and h3 for subsections. Do not skip levels just to get a smaller font.'],['Text meaning','Use <strong> for importance and <em> for emphasis. Browsers usually render these bold and italic, but their semantic meaning is more important than their default look.'],['Line breaks','Use <br> only when a line break is part of the content, such as an address or poem. Use CSS margins to create visual spacing.']],code:'<h1>Learning HTML</h1>\n<h2>Text elements</h2>\n<p>HTML gives content <strong>meaning</strong>.</p>\n<p>You can <em>emphasize</em> a word.</p>',output:'A main heading, a smaller section heading, and two paragraphs with emphasis.',tip:'A page should usually have one clear main heading, with nested section headings that describe the content.',quiz:{q:'Which element is normally used for a major section heading below h1?',opts:['<h5>','<h2>','<b>'],correct:1,why:'h2 represents a second-level heading beneath the main h1.'}},
{title:'Links, images & paths',time:12,intro:'Links connect pages and resources. Images can communicate information or add decoration. The correct path and useful alternative text make both more reliable and accessible.',goals:['Create a link with href','Add an image with alt text','Understand relative and absolute paths'],sections:[['Links','An anchor uses href to define its destination. Use descriptive link text such as “Read the HTML guide” rather than “click here”.'],['Images','The img element uses src for the image file and alt for a text alternative. If an image is purely decorative, an empty alt attribute is often appropriate.'],['File paths','A relative path such as images/cat.jpg is resolved from the current page location. An absolute URL includes the scheme and domain.']],code:'<a href="https://www.w3schools.com/html/">Learn HTML</a>\n<img src="images/profile.jpg" alt="Portrait of the author">',output:'A clickable link and an image placeholder when the image file exists.',tip:'Always check that the image path exists. Alt text should describe the image’s purpose, not repeat the filename.',quiz:{q:'Which attribute provides a text alternative for an image?',opts:['title','alt','href'],correct:1,why:'The alt attribute provides alternative text for an image.'}},
{title:'Lists, tables & forms',time:15,intro:'HTML includes specialized elements for grouped information and user input. Choose a list for related items, a table for tabular data, and a form for collecting information.',goals:['Choose ul, ol, and li correctly','Create a simple data table','Label form controls'],sections:[['Lists','Use ul for unordered lists and ol when order matters. Each list item belongs inside li.'],['Tables','Use table, tr, th, and td to represent data in rows and columns. Tables are for data relationships, not page layout.'],['Forms','A label associated with an input helps users understand what to enter. Use a suitable input type such as email when appropriate.']],code:'<ul>\n  <li>Practice HTML</li>\n  <li>Learn CSS</li>\n</ul>\n<form>\n  <label for="email">Email</label>\n  <input id="email" type="email" required>\n  <button type="submit">Join</button>\n</form>',output:'A two-item list and a labelled email input.',tip:'A label improves usability, and native input types can provide helpful browser validation.',quiz:{q:'Which element connects a visible label to an input by id?',opts:['for','src','class'],correct:0,why:'The label’s for value should match the input element’s id.'}}
]},
{id:'css',title:'CSS Styling',symbol:'#',level:'Beginner',category:'Web development',color:'#4387e8',bg:'#eaf2ff',desc:'Style content with selectors, the box model, layout, and responsive design.',duration:'2 hours',source:'https://www.w3schools.com/css/',sourceName:'W3Schools CSS',lessons:[
{title:'CSS basics & selectors',time:9,intro:'CSS (Cascading Style Sheets) describes how HTML content should look. A CSS rule combines a selector, which chooses elements, with declarations that set properties and values.',goals:['Explain selector, property, and value','Write a basic CSS rule','Select elements by class and id'],sections:[['Rule structure','In h1 { color: navy; }, h1 is the selector, color is the property, and navy is the value. Declarations end with semicolons.'],['Common selectors','A type selector targets elements such as p. A class selector starts with a dot, such as .card. An id selector starts with # and should identify one unique element in a document.'],['Adding CSS','You can use an external stylesheet, a style element, or an inline style. External stylesheets are usually easiest to maintain across multiple pages.']],code:'/* styles.css */\nbody { font-family: Arial, sans-serif; }\nh1 { color: #6558e8; }\n.card { padding: 16px; border-radius: 12px; }',output:'The heading becomes purple; elements with class="card" receive padding and rounded corners.',tip:'Prefer classes for reusable styles. Keep content in HTML and presentation rules in CSS.',quiz:{q:'What character begins a CSS class selector?',opts:['#','.','@'],correct:1,why:'A dot selects elements by class, such as .card.'}},
{title:'Colors, typography & cascade',time:10,intro:'CSS controls color, text appearance, and which rule wins when declarations conflict. The cascade considers origin, importance, specificity, and source order.',goals:['Set foreground and background colors','Style readable text','Understand specificity at a beginner level'],sections:[['Color and contrast','Use color and background-color to style text and surfaces. Ensure text contrast is strong enough for comfortable reading.'],['Typography','font-family chooses typefaces; font-size sets size; line-height controls line spacing; font-weight controls thickness. Relative units such as rem help scale text.'],['The cascade','If two normal declarations apply to the same property, a more specific selector generally wins. If specificity ties, the later rule wins. Avoid solving every conflict with !important.']],code:'body {\n  color: #20243a;\n  background-color: #f5f7fb;\n  font-family: Arial, sans-serif;\n  line-height: 1.6;\n}\n.notice { color: #176b50; }',output:'The page gets a soft background, dark text, and comfortable line spacing.',tip:'Do not rely on color alone to communicate errors or success; include text or an icon too.',quiz:{q:'Which property controls the space between lines of text?',opts:['font-style','line-height','text-decoration'],correct:1,why:'line-height controls the height of each line box.'}},
{title:'The CSS box model',time:11,intro:'Every element is laid out as a box. The content sits inside padding, then border, then margin. Understanding these layers makes spacing and sizing much easier to debug.',goals:['Identify content, padding, border, and margin','Explain margin versus padding','Use box-sizing: border-box'],sections:[['Four layers','Content is the text or image. Padding is inside the border. Border surrounds the padding. Margin creates space outside the border.'],['Sizing','With the default content-box model, width applies to content only. border-box includes padding and border within the declared width, which is often easier to reason about.'],['Spacing','Use padding when content needs breathing room inside a card. Use margin to separate that card from nearby elements.']],code:'* { box-sizing: border-box; }\n.card {\n  width: 300px;\n  padding: 20px;\n  border: 2px solid #6558e8;\n  margin: 16px 0;\n}',output:'A 300px-wide card whose padding and border are included in its width.',tip:'Applying box-sizing: border-box globally reduces unexpected width calculations.',quiz:{q:'Which box-model layer creates space outside the border?',opts:['Padding','Margin','Content'],correct:1,why:'Margin is the outer spacing around an element’s border.'}},
{title:'Flexbox, Grid & responsive layout',time:14,intro:'Flexbox helps arrange items along one axis, while CSS Grid is useful for rows and columns. Responsive design adapts a layout to different screen sizes.',goals:['Use display:flex for aligned items','Build a simple grid','Use a media query'],sections:[['Flexbox','display:flex places children in a flex formatting context. justify-content distributes items along the main axis; align-items aligns them on the cross axis.'],['Grid','display:grid with grid-template-columns defines columns. repeat(auto-fit, minmax(...)) can create responsive card grids.'],['Responsive design','Use flexible widths, readable spacing, and media queries when a layout needs to change at a breakpoint. Test with narrow and wide browser windows.']],code:'.cards {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n  gap: 16px;\n}\n@media (max-width: 600px) {\n  .page { padding: 16px; }\n}',output:'Cards fill available space and wrap into fewer columns on small screens.',tip:'Start with a layout that works on small screens, then add complexity where the content needs it.',quiz:{q:'Which CSS layout is especially useful for a two-dimensional row-and-column grid?',opts:['CSS Grid','font-family','text-transform'],correct:0,why:'CSS Grid is designed for two-dimensional layout.'}}
]},
{id:'js',title:'JavaScript Essentials',symbol:'JS',level:'Beginner',category:'Programming',color:'#c59b13',bg:'#fff7d8',desc:'Add logic and interactivity with variables, conditions, loops, and functions.',duration:'2.5 hours',source:'https://www.w3schools.com/js/',sourceName:'W3Schools JavaScript',lessons:[
{title:'Meet JavaScript',time:8,intro:'JavaScript is a programming language used to make web pages respond to actions, update content, and work with data. In a browser, scripts can interact with the Document Object Model (DOM).',goals:['Explain where JavaScript runs','Print a value with console.log','Understand statements and strings'],sections:[['Run your first code','console.log() writes a value to the browser developer console. It is useful for checking what your code is doing while you learn.'],['Values and statements','A string represents text, often written in quotes. A number represents numeric data. A statement is an instruction the program evaluates.'],['Errors are part of learning','Read error messages carefully and check spelling, brackets, quotes, and capitalization. JavaScript is case-sensitive.']],code:'console.log("Hello, JavaScript!");\nconsole.log(2 + 3);',output:'Hello, JavaScript!\n5',tip:'Try changing the text and the numbers, then run the example again to observe the result.',quiz:{q:'What does console.log(2 + 3) print?',opts:['23','5','2 + 3'],correct:1,why:'The + operator adds the two numeric values, producing 5.'}},
{title:'Variables & data types',time:12,intro:'Variables give names to values. Use const when you do not intend to reassign a binding, and let when reassignment is needed. Common data types include strings, numbers, booleans, undefined, and objects.',goals:['Declare variables with let and const','Recognize strings, numbers, and booleans','Use template literals'],sections:[['let and const','let score = 0; creates a variable that can later be reassigned. const user = "Mina"; creates a binding that cannot be reassigned. const does not make an object’s contents deeply immutable.'],['Data types','"Hello" is a string, 42 is a number, and true or false is a boolean. typeof can help inspect the type of a value.'],['Template literals','Backticks allow interpolation, such as `Hello, ${name}`. This is often easier to read than joining many strings with +.']],code:'const name = "Sakib";\nlet score = 0;\nscore = score + 10;\nconsole.log(`${name} scored ${score}`);',output:'Sakib scored 10',tip:'Use descriptive variable names. Prefer const by default, then use let if the value needs reassignment.',quiz:{q:'Which keyword should you usually use if a variable binding will not be reassigned?',opts:['const','let','change'],correct:0,why:'const communicates that the binding will not be reassigned.'}},
{title:'Conditions & comparisons',time:12,intro:'Conditions let a program choose which instructions to run. An if statement evaluates a condition; if it is truthy, the first block runs, otherwise an optional else block can run.',goals:['Use if and else','Compare values with ===','Combine conditions with && and ||'],sections:[['if and else','Use if (condition) { ... } to run code only when a condition is true. Add else for an alternative path.'],['Comparison','=== checks strict equality without converting types. For example, 5 === "5" is false because one value is a number and the other is a string.'],['Logical operators','&& means both conditions must be truthy. || means at least one condition must be truthy. Use parentheses when they make logic clearer.']],code:'const score = 82;\nif (score >= 80) {\n  console.log("Great work!");\n} else {\n  console.log("Keep practicing.");\n}',output:'Great work!',tip:'Prefer === and !== for predictable comparisons. Test both the true and false paths of a condition.',quiz:{q:'What does 5 === "5" evaluate to?',opts:['true','false','It prints 5'],correct:1,why:'Strict equality compares both value and type; number 5 is not string "5".'}},
{title:'Loops, arrays & functions',time:16,intro:'Loops repeat work, arrays store ordered collections, and functions package reusable logic. Together they form a core toolkit for writing useful programs.',goals:['Create and read an array','Use a for loop','Define and call a function'],sections:[['Arrays','const colors = ["red", "blue"]; stores two items. Array positions start at index 0, so colors[0] is "red".'],['Loops','A for loop repeats while its condition remains true. Make sure the loop changes the value that controls the condition, or it may never stop.'],['Functions','A function can accept parameters and return a value. Calling a function runs its body; return sends a result back to the caller.']],code:'function add(a, b) {\n  return a + b;\n}\nconst numbers = [2, 4, 6];\nfor (let i = 0; i < numbers.length; i++) {\n  console.log(numbers[i]);\n}\nconsole.log(add(3, 5));',output:'2\n4\n6\n8',tip:'Write small functions that do one clear job. Test them with normal, boundary, and unexpected inputs.',quiz:{q:'What is the index of the first array item?',opts:['0','1','-1'],correct:0,why:'JavaScript arrays use zero-based indexing.'}}
]},
{id:'python',title:'Python Starter',symbol:'Py',level:'Beginner',category:'Programming',color:'#3476b8',bg:'#e9f4ff',desc:'Learn Python syntax, values, conditions, loops, and reusable functions.',duration:'2 hours',source:'https://www.w3schools.com/python/',sourceName:'W3Schools Python',lessons:[
{title:'Your first Python program',time:8,intro:'Python is a general-purpose programming language known for readable syntax. It is used for automation, data analysis, web backends, scripting, and many other tasks.',goals:['Recognize Python statements','Print text and numbers','Understand indentation'],sections:[['Print output','print() displays values. Strings use quotes; arithmetic expressions can be printed directly.'],['Indentation matters','Python uses indentation to mark blocks of code instead of curly braces. Use consistent indentation, commonly four spaces per level.'],['Comments','A # starts a single-line comment. Comments should explain intent or context rather than repeat obvious code.']],code:'print("Hello, Python!")\nprint(2 + 3)\n# This is a comment',output:'Hello, Python!\n5',tip:'Copy the example into a Python interpreter and change the values. Indentation errors are common at first.',quiz:{q:'Which function displays output in a basic Python program?',opts:['echo()','print()','writeLine()'],correct:1,why:'print() writes values to the output stream.'}},
{title:'Variables & basic types',time:10,intro:'A Python variable is a name that refers to a value. Python determines the type at runtime, so you do not write a type declaration when assigning a variable.',goals:['Assign values to names','Identify strings, integers, and booleans','Convert simple input values'],sections:[['Assignment','name = "Rafi" binds the name to a string. score = 12 binds score to an integer. The equals sign is assignment, not a mathematical equality test.'],['Common types','str stores text, int stores whole numbers, float stores decimal numbers, and bool stores True or False. Python capitalization matters.'],['Input conversion','input() returns text. Convert it with int() or float() before doing arithmetic on numeric input.']],code:'name = "Rafi"\nage = 20\nis_learning = True\nprint(name, age, is_learning)\nprint(type(age))',output:'Rafi 20 True\n<class \'int\'>',tip:'When using input() for a number, remember that the input initially arrives as a string.',quiz:{q:'What type does input() return?',opts:['Always int','Always str','Always bool'],correct:1,why:'input() returns a string; convert it when you need a number.'}},
{title:'Conditions & loops',time:13,intro:'if/elif/else lets Python make decisions. for loops commonly iterate over items in a sequence, while while loops continue as long as a condition is true.',goals:['Write if/else blocks','Loop over a range','Avoid accidental infinite loops'],sections:[['Conditions','Python uses a colon after the condition and indentation for the block. Comparisons include ==, !=, <, >, <=, and >=.'],['for and range','range(5) produces numbers 0 through 4. A for loop can iterate over strings, lists, and other iterable objects.'],['while loops','A while loop repeats while its condition is true. Update the relevant state inside the loop so it can eventually finish.']],code:'score = 75\nif score >= 50:\n    print("Pass")\nelse:\n    print("Try again")\n\nfor number in range(3):\n    print(number)',output:'Pass\n0\n1\n2',tip:'Indentation is part of Python syntax. A loop should have a clear stopping condition.',quiz:{q:'What values are produced by range(3)?',opts:['1, 2, 3','0, 1, 2','0, 1, 2, 3'],correct:1,why:'range(3) starts at zero and stops before three.'}},
{title:'Lists & functions',time:15,intro:'Lists hold ordered collections that can change. Functions group reusable instructions and can accept arguments and return results.',goals:['Create and update a list','Define a function with def','Return a calculated value'],sections:[['Lists','items = ["pen", "book"] creates a list. append() adds an item. Indexing starts at zero, and len() returns the number of items.'],['Functions','Use def followed by a name, parentheses, and a colon. The indented body runs when the function is called.'],['Return values','return sends a result to the caller. print displays something; it does not replace return when another part of the program needs the calculated value.']],code:'def multiply(a, b):\n    return a * b\n\nitems = ["pen", "book"]\nitems.append("bag")\nprint(items)\nprint(multiply(4, 3))',output:"['pen', 'book', 'bag']\n12",tip:'Keep functions focused and use names that describe what they return or do.',quiz:{q:'Which keyword defines a function in Python?',opts:['function','def','func'],correct:1,why:'Python uses def to begin a function definition.'}}
]},
{id:'cpp',title:'C++ Fundamentals',symbol:'C+',level:'Beginner',category:'Programming',color:'#387bc0',bg:'#eaf2ff',desc:'Understand C++ program structure, variables, decisions, loops, and functions.',duration:'2.5 hours',source:'https://www.w3schools.com/cpp/',sourceName:'W3Schools C++',lessons:[
{title:'Structure of a C++ program',time:10,intro:'C++ is a compiled, general-purpose programming language. A typical beginner program includes a header, a main function, statements, and a return value.',goals:['Recognize the main function','Use cout for output','Understand semicolons and braces'],sections:[['Header and main','The iostream header provides standard input/output tools such as std::cout. Program execution normally begins in main.'],['Statements','Most simple C++ statements end with a semicolon. Braces group statements into a block.'],['Compile and run','A compiler translates source code into a program. If compilation fails, read the first error carefully; later errors may be consequences of the first one.']],code:'#include <iostream>\n\nint main() {\n    std::cout << "Hello, C++!\\n";\n    return 0;\n}',output:'Hello, C++!',tip:'If your compiler complains, check spelling, missing semicolons, matching braces, and whether the file is compiled as C++.',quiz:{q:'Which function is the usual entry point of a C++ program?',opts:['start()','main()','run()'],correct:1,why:'A standard hosted C++ program begins execution in main.'}},
{title:'Variables & types',time:11,intro:'C++ variables have declared types. The type determines what values a variable can represent and what operations are available.',goals:['Declare int, double, and string values','Understand initialization','Print variables'],sections:[['Declaring variables','int age = 20; declares an integer. double price = 9.5; represents a floating-point value. std::string name = "Ava"; stores text when the string header is included.'],['Initialization','Initialize variables when declaring them so they start with a known value. Uninitialized local fundamental variables may contain indeterminate values.'],['Constants','Use const when a value should not be reassigned after initialization. Choose names that describe the purpose of the value.']],code:'#include <iostream>\n#include <string>\nint main() {\n    int age = 20;\n    std::string name = "Ava";\n    std::cout << name << " is " << age;\n    return 0;\n}',output:'Ava is 20',tip:'Choose a type that matches the data. Be careful when converting between integers and floating-point values.',quiz:{q:'Which type is commonly used for whole numbers?',opts:['int','string','bool only'],correct:0,why:'int represents integer values.'}},
{title:'Conditions & loops',time:13,intro:'Conditions choose between paths. Loops repeat statements. These constructs let a program respond to input and process collections or ranges of values.',goals:['Use if and else','Write a for loop','Understand loop conditions'],sections:[['Conditions','if (score >= 50) checks whether score is at least 50. Parentheses contain the condition and braces contain the body.'],['for loops','A common for loop has initialization, a condition, and an update expression. Make sure the condition eventually becomes false.'],['Comparisons','Use == to compare values for equality and = to assign a value. Confusing them is a common beginner mistake.']],code:'#include <iostream>\nint main() {\n    for (int i = 1; i <= 3; i++) {\n        std::cout << i << "\\n";\n    }\n    return 0;\n}',output:'1\n2\n3',tip:'Trace the loop by hand: initial value, condition check, body, update, then repeat.',quiz:{q:'Which operator compares two values for equality in C++?',opts:['=','==','=>'],correct:1,why:'== compares equality; = assigns a value.'}},
{title:'Functions & arrays',time:16,intro:'Functions make logic reusable. Arrays store a fixed number of same-type elements in adjacent positions. Standard containers such as std::vector are often safer and more flexible than raw arrays.',goals:['Define and call a function','Declare an array','Understand zero-based indexing'],sections:[['Functions','A function declaration includes a return type, name, parameters, and body. return sends a value to the caller when the function returns a value.'],['Arrays','int scores[3] = {70, 85, 90}; creates three integers. The valid indices are 0, 1, and 2. Accessing outside the bounds is unsafe.'],['Practice','Use a loop to visit each valid index. In modern C++, consider std::vector when the collection size may change.']],code:'#include <iostream>\nint add(int a, int b) {\n    return a + b;\n}\nint main() {\n    int scores[3] = {70, 85, 90};\n    std::cout << add(scores[0], scores[1]);\n    return 0;\n}',output:'155',tip:'Do not access an array using an index outside its valid range. Learn std::vector after you understand arrays.',quiz:{q:'What is the first index of a C++ array?',opts:['0','1','-1'],correct:0,why:'C++ arrays use zero-based indexing.'}}
]}
];
const allLessons=()=>courses.flatMap(c=>c.lessons.map((l,i)=>({...l,courseId:c.id,courseTitle:c.title,index:i,key:`${c.id}-${i}`,course:c})));
const lessonList=allLessons();
const defaults={completed:[],quizScores:{},challenges:[],bookmarks:[],notes:[],tasks:[],minutes:0,theme:'light'};
let state;try{state={...defaults,...JSON.parse(localStorage.getItem('codepath-v2')||'{}')};}catch(e){state={...defaults};}
let current={view:'dashboard',courseId:'html',lessonIndex:0};
let supabaseClient=null, signedInUser=null, cloudSyncTimer=null, cloudLoaded=false, authMode='signin';
const cloudFields=['completed','quizScores','challenges','minutes'];
function cloudPayload(){const out={};for(const k of cloudFields)out[k]=state[k];return out;}
function mergeCloudProgress(remote){if(!remote||typeof remote!=='object')return;state.completed=[...new Set([...(state.completed||[]),...(remote.completed||[])])];state.challenges=[...new Set([...(state.challenges||[]),...(remote.challenges||[])])];state.quizScores={...(remote.quizScores||{}),...(state.quizScores||{})};state.minutes=Math.max(Number(state.minutes)||0,Number(remote.minutes)||0);}
function save(){try{localStorage.setItem('codepath-v2',JSON.stringify(state));}catch(e){toast('Browser storage is unavailable. Your changes may not persist.');}if(signedInUser&&supabaseClient&&cloudLoaded){clearTimeout(cloudSyncTimer);cloudSyncTimer=setTimeout(syncProgressToCloud,650);}}
async function syncProgressToCloud(){if(!signedInUser||!supabaseClient||!cloudLoaded)return;const payload={user_id:signedInUser.id,progress:cloudPayload(),updated_at:new Date().toISOString()};const {error}=await supabaseClient.from('codemagic_progress').upsert(payload,{onConflict:'user_id'});if(error){console.error('Cloud progress sync failed:',error.message);setAuthMessage('Cloud sync failed. Your changes are still saved on this device. Check your Supabase setup.');}else{updateAuthButton();}}
function setAuthMessage(message,isError=false){const el=$('#authMessage');if(el){el.textContent=message;el.classList.toggle('error',isError);}}
function updateAuthButton(){const b=$('#authOpen');if(b)b.textContent=signedInUser?(signedInUser.email||'Account'):'Sign in';const acc=$('#authAccount'),form=$('#authForm'),reset=$('#authReset'),mode=$('#authModeToggle');if(acc)acc.hidden=!signedInUser;if(form)form.hidden=!!signedInUser;if(reset)reset.hidden=!!signedInUser||authMode==='recovery';if(mode){mode.hidden=authMode==='recovery';mode.textContent=authMode==='signin'?'Create account':'I already have an account';}const em=$('#authUserEmail');if(em)em.textContent=signedInUser?`Signed in as ${signedInUser.email}`:'';syncAuthModeUI();}
function syncAuthModeUI(){const title=$('#authTitle'),submit=$('#authSubmit'),password=$('#authPassword'),toggle=$('#authModeToggle'),reset=$('#authReset');if(title)title.textContent=authMode==='signup'?'Create your CodeMagic account':authMode==='recovery'?'Set a new password':'Sign in to CodeMagic';if(submit)submit.textContent=authMode==='signup'?'Create account':authMode==='recovery'?'Update password':'Sign in';if(password)password.setAttribute('autocomplete',authMode==='signin'?'current-password':'new-password');if(toggle)toggle.hidden=authMode==='recovery';if(reset)reset.hidden=authMode==='recovery'||!!signedInUser;}
function openAuth(){const b=$('#authBackdrop');if(b){b.hidden=false;updateAuthButton();setAuthMessage(supabaseClient?'':'Add your Supabase URL and publishable key to supabase-config.js, then reload.');$('#authEmail')?.focus();}}
function closeAuth(){const b=$('#authBackdrop');if(b)b.hidden=true;}
async function initSupabase(){const url=window.CODEMAGIC_SUPABASE_URL,key=window.CODEMAGIC_SUPABASE_ANON_KEY;if(!window.supabase||!url||!key||url.includes('YOUR_PROJECT_ID')||key.includes('YOUR_SUPABASE')){updateAuthButton();return;}try{supabaseClient=window.supabase.createClient(url,key);const recoveryLink=/(?:^|[&#])type=recovery(?:&|$)/.test(window.location.hash);const {data:{session}}=await supabaseClient.auth.getSession();if(session&&!recoveryLink)await handleSignedIn(session.user);if(recoveryLink){authMode='recovery';openAuth();syncAuthModeUI();setAuthMessage('Enter a new password for your account.');}supabaseClient.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_IN'&&session?.user&&authMode!=='recovery')handleSignedIn(session.user);else if(event==='PASSWORD_RECOVERY'){authMode='recovery';signedInUser=null;cloudLoaded=false;openAuth();syncAuthModeUI();setAuthMessage('Enter a new password for your account.');}else if(event==='SIGNED_OUT'){signedInUser=null;cloudLoaded=false;authMode='signin';updateAuthButton();setAuthMessage('You are signed out. Progress remains saved on this device.');}});updateAuthButton();if(recoveryLink){authMode='recovery';openAuth();syncAuthModeUI();setAuthMessage('Enter a new password for your account.');}}catch(e){console.error(e);setAuthMessage('Could not initialize Supabase. Check supabase-config.js. ',true);}}
async function handleSignedIn(user){signedInUser=user;cloudLoaded=false;updateAuthButton();setAuthMessage('Loading your cloud progress…');const priorOwner=localStorage.getItem('codepath-cloud-owner');if(priorOwner&&priorOwner!==user.id){state.completed=[];state.quizScores={};state.challenges=[];state.minutes=0;}const {data,error}=await supabaseClient.from('codemagic_progress').select('progress').eq('user_id',user.id).maybeSingle();if(error){console.error('Cloud progress load failed:',error.message);setAuthMessage('Signed in, but cloud progress could not load. Run the SQL setup and check RLS policies. Local data has been kept.',true);cloudLoaded=false;return;}if(data?.progress)mergeCloudProgress(data.progress);cloudLoaded=true;try{localStorage.setItem('codepath-v2',JSON.stringify(state));localStorage.setItem('codepath-cloud-owner',user.id);}catch(e){}render();await syncProgressToCloud();setAuthMessage(data?.progress?'Signed in. Your learning progress is synced.':'Account ready. Your current progress has been saved to the cloud.');updateAuthButton();}
async function submitAuth(e){e.preventDefault();if(!supabaseClient){setAuthMessage('First add your Supabase project URL and publishable/anon key to supabase-config.js, then reload.',true);return;}const email=$('#authEmail').value.trim(),password=$('#authPassword').value;const submit=$('#authSubmit');submit.disabled=true;setAuthMessage(authMode==='signin'?'Signing in…':authMode==='recovery'?'Updating your password…':'Creating account…');try{if(authMode==='signin'){const {error}=await supabaseClient.auth.signInWithPassword({email,password});if(error)throw error;setAuthMessage('Signed in successfully. Loading your progress…');}else if(authMode==='recovery'){const {data,error}=await supabaseClient.auth.updateUser({password});if(error)throw error;authMode='signin';if(data?.user)await handleSignedIn(data.user);syncAuthModeUI();setAuthMessage('Password updated successfully. You are signed in.');}else{const {data,error}=await supabaseClient.auth.signUp({email,password});if(error)throw error;if(data.session){await handleSignedIn(data.user);setAuthMessage('Account created. You are signed in.');}else{setAuthMessage('Account created. Check your email to confirm your account, then sign in.');authMode='signin';updateAuthButton();}}}catch(err){setAuthMessage(err.message||'Authentication failed.',true);}finally{submit.disabled=false;}}

function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2400);}
function pageHead(kicker,title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action?`<div>${action}</div>`:''}</div>`;}
function courseCard(c){const done=c.lessons.filter((l,i)=>state.completed.includes(`${c.id}-${i}`)).length;return `<article class="course-card"><div class="course-top"><div class="course-symbol" style="--course-color:${c.color};--course-bg:${c.bg}">${c.symbol}</div><span class="tag">${c.level}</span></div><h3>${c.title}</h3><p>${c.desc}</p><div class="progress"><span style="width:${done/c.lessons.length*100}%"></span></div><div class="course-foot"><span>${done}/${c.lessons.length} lessons · ${c.duration}</span><button class="button soft" data-open-course="${c.id}">${done?'Continue':'Start course'} →</button></div></article>`;}
function render(){const content=$('#content');const titles={dashboard:'Overview',courses:'All courses',lesson:'Lesson',playground:'Code playground',challenges:'Practice & quizzes',projects:'Projects',notes:'My notes',bookmarks:'Bookmarks',planner:'Study planner'};$('#pageCrumb').textContent=titles[current.view]||'Overview';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===current.view));switch(current.view){case'dashboard':content.innerHTML=dashboard();break;case'courses':content.innerHTML=coursesView();break;case'lesson':content.innerHTML=lessonView();break;case'playground':content.innerHTML=playgroundView();break;case'challenges':content.innerHTML=challengesView();break;case'projects':content.innerHTML=projectsView();break;case'notes':content.innerHTML=notesView();break;case'bookmarks':content.innerHTML=bookmarksView();break;case'planner':content.innerHTML=plannerView();break;}if(current.view==='lesson')window.scrollTo({top:0,behavior:'smooth'});}
function dashboard(){const completed=state.completed.length,percent=Math.round(completed/lessonList.length*100),next=lessonList.find(l=>!state.completed.includes(l.key))||lessonList[0];return `${pageHead('YOUR LEARNING SPACE','Make today <span style="color:var(--accent)">count.</span>','Build practical programming skills with guided lessons, examples, quizzes, and projects.',`<span class="date-pill">◷ ${new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</span>`)}<section class="hero"><div class="hero-copy"><div class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</div><h2>Learn the basics.<br><em>Build the real thing.</em></h2><p>Follow a clear path from first concepts to hands-on practice. Your progress is saved on this device and syncs to your account when you sign in.</p><button class="button primary" data-open-lesson="${next.key}">Continue learning →</button></div><div class="hero-art"><div class="code-card"><div class="dim">// your next step</div><div><span class="purple">const</span> skills = [</div><div>&nbsp;&nbsp;<span class="green">"learn"</span>, <span class="green">"practice"</span>,</div><div>&nbsp;&nbsp;<span class="green">"build"</span></div><div>];</div><div class="yellow">console.log("Keep going!");</div></div></div></section><section class="stats-grid"><article class="stat-card"><div class="stat-label">Lessons completed <span class="stat-icon">✓</span></div><strong class="stat-number">${completed}<span style="font-size:13px;color:var(--muted)"> / ${lessonList.length}</span></strong><p>Across all learning paths</p><div class="progress"><span style="width:${percent}%"></span></div></article><article class="stat-card"><div class="stat-label">Courses available <span class="stat-icon">▤</span></div><strong class="stat-number">${courses.length}</strong><p>Start with any beginner course</p></article><article class="stat-card"><div class="stat-label">Quiz attempts <span class="stat-icon">✳</span></div><strong class="stat-number">${Object.keys(state.quizScores).length+state.challenges.length}</strong><p>Practice and check your understanding</p></article><article class="stat-card"><div class="stat-label">Study tasks done <span class="stat-icon">◷</span></div><strong class="stat-number">${state.tasks.filter(t=>t.done).length}</strong><p>Tasks completed in your planner</p></article></section><div class="section-title"><div><h2>Choose a learning path</h2><p>Each course includes lessons, examples, practice questions, and learning links.</p></div><button class="text-button" data-view="courses">Explore all courses →</button></div><div class="course-grid">${courses.map(courseCard).join('')}</div><div class="section-title"><div><h2>Pick up where you left off</h2><p>Your next unfinished lesson is ready.</p></div></div><div class="panel"><div class="continue-row"><div class="row-symbol">${next.course.symbol}</div><div class="row-copy"><strong>${next.course.title}: ${next.title}</strong><small>${next.time} min · ${next.course.level} · ${next.course.category}</small></div><button class="row-action" data-open-lesson="${next.key}">Open lesson →</button></div></div>`;}
function coursesView(){return `${pageHead('THE COURSE LIBRARY','Explore courses','Choose a structured learning path. Use search to find a course or a specific concept.') }<div class="filter-row"><input class="field search-field" id="courseSearch" placeholder="Filter courses by name, topic, or language…"><select class="field" id="levelFilter"><option value="all">All levels</option><option>Beginner</option></select></div><div class="course-grid" id="courseGrid">${courses.map(courseCard).join('')}</div><div class="section-title"><div><h2>Reference libraries</h2><p>These links provide additional explanations and reference material.</p></div></div><div class="resource-grid">${resourceCard('W3Schools','Short explanations and examples across many programming topics.','https://www.w3schools.com/',['HTML, CSS and JavaScript','Python, C++, SQL and more','Examples and exercises'])}${resourceCard('MDN Web Docs','A detailed reference and learning curriculum for web development.','https://developer.mozilla.org/en-US/docs/Learn_web_development',['HTML semantics and accessibility','CSS layout and responsive design','JavaScript fundamentals and challenges'])}</div>`;}
function resourceCard(title,desc,url,items){return `<article class="resource-card"><div class="eyebrow">EXTERNAL LEARNING RESOURCE</div><h3>${title}</h3><p>${desc}</p><ul>${items.map(x=>`<li>${x}</li>`).join('')}</ul><a class="button secondary" href="${url}" target="_blank" rel="noopener noreferrer">Visit ${title} ↗</a></article>`;}
function lessonView(){const c=courses.find(x=>x.id===current.courseId)||courses[0];current.courseId=c.id;current.lessonIndex=Math.max(0,Math.min(c.lessons.length-1,current.lessonIndex));const i=current.lessonIndex,l=c.lessons[i],key=`${c.id}-${i}`,done=state.completed.includes(key),idx=lessonList.findIndex(x=>x.key===key),quizState=state.quizScores[key];return `${pageHead(c.title.toUpperCase(),c.title,'Learn step by step. Read the explanation, run the example, then answer the quiz.',`<button class="button secondary" data-view="courses">← All courses</button>`)}<div class="lesson-layout"><aside class="lesson-sidebar"><h3>Course contents <span style="color:var(--muted);font-weight:400">(${c.lessons.length})</span></h3>${c.lessons.map((x,j)=>`<button class="lesson-nav ${j===i?'active':''} ${state.completed.includes(`${c.id}-${j}`)?'done':''}" data-course-lesson="${j}"><span>${state.completed.includes(`${c.id}-${j}`)?'✓':String(j+1).padStart(2,'0')}</span><span>${esc(x.title)}</span></button>`).join('')}</aside><div class="lesson-main"><article class="lesson-article"><div class="lesson-meta"><span>${c.level.toUpperCase()}</span><span>•</span><span>LESSON ${i+1} OF ${c.lessons.length}</span><span>•</span><span>${l.time} MIN READ</span>${done?'<span class="tag">COMPLETED ✓</span>':''}</div><h1>${esc(l.title)}</h1><p>${esc(l.intro)}</p><div class="callout"><strong>What you will learn</strong><ul style="margin:5px 0 0;padding-left:18px">${l.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul></div>${l.sections.map((s,j)=>`<h2>${j+1}. ${esc(s[0])}</h2><p>${esc(s[1])}</p>`).join('')}<h2>Example: try to understand every line</h2><p>Read the code and notice how the syntax relates to the explanation above.</p><div class="lesson-example"><div class="example-head"><span>Example code</span><button class="text-button" data-copy-code>Copy code</button></div><div class="code-sample" id="lessonCode">${esc(l.code)}</div></div><div class="lesson-example"><div class="example-head"><span>Expected result / behavior</span><span>OUTPUT</span></div><div class="example-body"><pre>${esc(l.output)}</pre></div></div><div class="callout"><strong>Remember</strong>${esc(l.tip)}</div><div class="toolbar"><button class="button primary" data-use-example="${key}">Try this in the playground ↗</button><button class="button secondary" data-bookmark-lesson="${key}">♡ Save lesson</button></div><section class="quiz" id="lessonQuiz"><div class="eyebrow">QUICK KNOWLEDGE CHECK</div><h3>Test your understanding</h3><div class="quiz-question">${esc(l.quiz.q)}</div>${l.quiz.opts.map((o,j)=>`<label class="quiz-option"><input type="radio" name="lessonAnswer" value="${j}" ${quizState&&quizState.selected===j?'checked':''}> <span>${esc(o)}</span></label>`).join('')}<div class="toolbar"><button class="button primary" data-check-quiz="${key}">Check answer</button><span class="hint">Take your time. You can try again.</span></div><div class="quiz-feedback" id="quizFeedback">${quizState?`${quizState.correct?'Correct! ':'Not quite. '}${esc(l.quiz.why)}`:''}</div></section><div class="source-links"><a href="${c.source}" target="_blank" rel="noopener noreferrer">Study more: ${c.sourceName} ↗</a>${c.id==='html'||c.id==='css'||c.id==='js'?'<a href="https://developer.mozilla.org/en-US/docs/Learn_web_development" target="_blank" rel="noopener noreferrer">MDN Web Docs ↗</a>':''}</div><div class="lesson-footer"><button class="button secondary" data-prev-lesson ${i===0?'disabled':''}>← Previous lesson</button><button class="button primary" data-complete="${key}">${done?'Completed ✓':'Mark complete'} · Next →</button></div></article></div></div>`;}
function playgroundView(){return `${pageHead('EXPERIMENT SPACE','Code playground','Write HTML, CSS, and JavaScript together, then run it in a preview. The preview runs in a sandboxed frame.') }<div class="panel"><div class="toolbar"><button class="button primary" id="runCode">▶ Run code</button><button class="button secondary" id="resetCode">Reset example</button><span class="hint">Tip: edit the heading text, colors, or button behavior.</span></div><div class="editor-grid"><section class="editor-panel"><div class="editor-head"><span>index.html · HTML + CSS + JS</span><span>EDITOR</span></div><textarea id="playCode" class="editor" spellcheck="false" aria-label="Code editor"><!doctype html>
<html>
<head>
<style>
body { font-family: Arial, sans-serif; padding: 24px; color: #24243b; }
.card { max-width: 380px; padding: 22px; border-radius: 14px; background: #f0efff; }
button { border: 0; border-radius: 8px; padding: 10px 14px; background: #6558e8; color: white; cursor: pointer; }
</style>
</head>
<body>
<div class="card">
  <h1>Hello, coder!</h1>
  <p id="message">Change the code and click Run.</p>
  <button onclick="document.getElementById('message').textContent = 'You made it work!'">Try me</button>
</div>
</body>
</html></textarea></section><section class="editor-panel"><div class="editor-head"><span>Live preview</span><span id="previewStatus">READY</span></div><iframe id="previewFrame" class="preview" sandbox="allow-scripts" title="Sandboxed code preview"></iframe></section></div><p class="hint">Safety note: this is a local learning playground, not a production environment. The preview is sandboxed and does not have network access granted by this page.</p></div>`;}
const challenges=[{id:'html-heading',title:'HTML heading',topic:'HTML',q:'Which tag creates the main level-one heading?',hint:'It is the tag with the number one.',answers:['<h1>','h1'],explain:'Use the h1 element for the main heading of a page.'},{id:'css-class',title:'CSS class selector',topic:'CSS',q:'Which selector targets elements with class="card"?',hint:'A class selector starts with a dot.',answers:['.card'],explain:'A dot followed by the class name targets that class.'},{id:'js-const',title:'JavaScript constants',topic:'JavaScript',q:'Which keyword declares a binding that cannot be reassigned?',hint:'It is the opposite of choosing let for reassignment.',answers:['const'],explain:'const prevents reassignment of the binding.'},{id:'py-print',title:'Python output',topic:'Python',q:'Write the Python function name used to display output.',hint:'It is six letters and has parentheses.',answers:['print','print()'],explain:'print() displays values in Python.'},{id:'cpp-equal',title:'C++ comparison',topic:'C++',q:'Which operator checks equality?',hint:'It uses two equals signs.',answers:['=='],explain:'== compares values; a single = is assignment.'}];
function challengesView(){return `${pageHead('PRACTICE MAKES PROGRESS','Practice & quizzes','Short exercises help you recall concepts. Type your answer, check it, and use hints if you get stuck.')}${challenges.map(c=>`<article class="challenge-card"><div class="eyebrow">${c.topic.toUpperCase()} · PRACTICE</div><h3>${c.title}</h3><p>${c.q}</p><div class="answer-row"><input class="field" id="answer-${c.id}" placeholder="Type your answer…" aria-label="Answer for ${c.title}"><button class="button primary" data-check-challenge="${c.id}">${state.challenges.includes(c.id)?'Completed ✓':'Check answer'}</button><button class="button secondary" data-hint="${c.id}">Hint</button></div><div class="feedback" id="feedback-${c.id}">${state.challenges.includes(c.id)?'Correct — completed!':''}</div></article>`).join('')}`;}
const projects=[{title:'Personal profile page',level:'Beginner',desc:'Build a responsive profile page with a heading, bio, skills, and links.',steps:['Create semantic HTML sections','Style a readable card and page layout','Make it responsive on mobile','Add accessible links and image alt text'],starter:'Start with a main element, an h1, a short paragraph, and a list of skills.'},{title:'Interactive tip calculator',level:'Beginner',desc:'Practice variables, input values, arithmetic, and DOM updates.',steps:['Add bill and tip inputs','Read and validate the values','Calculate the tip and total','Show a helpful result and handle invalid input'],starter:'Create two number inputs and a button. On click, calculate bill × tip percentage.'},{title:'To-do list',level:'Beginner',desc:'Make a small task list with add, complete, and delete interactions.',steps:['Create an input and add button','Render each task as a list item','Toggle completion state','Add a delete button and empty state'],starter:'Store tasks in an array of objects and render the list after each change.'},{title:'Study dashboard',level:'Intermediate',desc:'Combine cards, a progress bar, and saved learning goals in a dashboard.',steps:['Plan the card layout with CSS Grid','Add goals and a progress count','Save state to localStorage','Test keyboard use and mobile layouts'],starter:'Build three summary cards, then update the progress number when a goal checkbox changes.'}];
function projectsView(){return `${pageHead('LEARN BY BUILDING','Project lab','Apply concepts to small, realistic projects. Follow each checklist and save your progress.') }<div class="course-grid">${projects.map((p,i)=>`<article class="course-card"><div class="course-top"><div class="course-symbol">${['▧','∑','✓','◫'][i]}</div><span class="tag">${p.level}</span></div><h3>${p.title}</h3><p>${p.desc}</p><div class="course-foot"><span>${p.steps.length} steps</span><button class="button soft" data-project="${i}">View checklist →</button></div></article>`).join('')}</div><div id="projectDetails"></div>`;}
function notesView(){return `${pageHead('YOUR PERSONAL LIBRARY','My notes','Save your own explanations, code snippets, and questions. Notes are stored in this browser.') }<div class="panel"><form id="noteForm"><div class="form-grid"><input class="field full" id="noteTitle" placeholder="Note title (e.g. CSS box model)" required maxlength="100"><textarea class="field full" id="noteBody" placeholder="Write the idea in your own words…" rows="5" required></textarea></div><div class="toolbar"><button class="button primary" type="submit">Save note</button></div></form><div class="section-title"><div><h2>Saved notes (${state.notes.length})</h2></div></div>${state.notes.length?state.notes.slice().reverse().map(n=>`<article class="note-card"><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><div class="note-actions"><span class="hint">${new Date(n.created).toLocaleDateString()}</span><button class="text-button" data-delete-note="${n.id}">Delete</button></div></article>`).join(''):'<div class="empty">Your notes will appear here after you save one.</div>'}</div>`;}
function bookmarksView(){return `${pageHead('SAVE IT FOR LATER','Bookmarks','Keep lessons and learning resources close at hand.') }<div class="panel">${state.bookmarks.length?state.bookmarks.map((b,i)=>`<div class="continue-row"><div class="row-symbol">♡</div><div class="row-copy"><strong>${esc(b.title)}</strong><small>${esc(b.type)}</small></div>${b.key?`<button class="row-action" data-open-lesson="${b.key}">Open →</button>`:''}<button class="text-button" data-remove-bookmark="${i}">Remove</button></div>`).join(''):'<div class="empty">No bookmarks yet. Open a lesson and choose “Save lesson”.</div>'}</div>`;}
function plannerView(){return `${pageHead('BUILD A CONSISTENT ROUTINE','Study planner','Add a realistic task, set a due date, and check it off when finished. Browser notifications are not required.') }<div class="panel"><form id="taskForm" class="filter-row"><input class="field search-field" id="taskTitle" placeholder="What do you want to study?" maxlength="120" required><input class="field" id="taskDate" type="date"><button class="button primary" type="submit">+ Add task</button></form><div class="section-title"><div><h2>Your tasks</h2><p>Saved locally in this browser.</p></div><button class="text-button" id="clearDone">Clear completed</button></div>${state.tasks.length?state.tasks.map(t=>`<label class="planner-row"><input type="checkbox" data-task-toggle="${t.id}" ${t.done?'checked':''}><div class="row-copy"><strong style="${t.done?'text-decoration:line-through;color:var(--muted)':''}">${esc(t.title)}</strong><small>${t.date?`Due ${esc(t.date)}`:'No due date'}</small></div><button type="button" class="text-button" data-delete-task="${t.id}">Delete</button></label>`).join(''):'<div class="empty">No tasks yet. Add your next study session above.</div>'}</div>`;}
function go(view){current.view=view;$('#sidebar').classList.remove('open');render();}
function openLessonByKey(key){const l=lessonList.find(x=>x.key===key);if(!l)return;current={view:'lesson',courseId:l.courseId,lessonIndex:l.index};render();}
function copyText(text){if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text).then(()=>toast('Copied to clipboard')).catch(()=>toast('Copy was blocked by the browser.'));}else{const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();try{document.execCommand('copy');toast('Copied to clipboard');}catch(e){toast('Unable to copy automatically.');}ta.remove();}}
const starterCode=`<!doctype html>\n<html>\n<head>\n<style>\nbody { font-family: Arial, sans-serif; padding: 24px; color: #24243b; }\n.card { max-width: 380px; padding: 22px; border-radius: 14px; background: #f0efff; }\nbutton { border: 0; border-radius: 8px; padding: 10px 14px; background: #6558e8; color: white; cursor: pointer; }\n</style>\n</head>\n<body>\n<div class="card">\n  <h1>Hello, coder!</h1>\n  <p id="message">Change the code and click Run.</p>\n  <button onclick="document.getElementById('message').textContent = 'You made it work!'">Try me</button>\n</div>\n</body>\n</html>`;
function runCode(){const frame=$('#previewFrame'),code=$('#playCode')?.value;if(!frame||code==null)return;frame.srcdoc=code;$('#previewStatus').textContent='UPDATED';}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-view]');if(!b)return;if(b.dataset.view){go(b.dataset.view);return;}if(b.dataset.openCourse){const c=courses.find(x=>x.id===b.dataset.openCourse);if(c)openLessonByKey(`${c.id}-0`);return;}if(b.dataset.openLesson){openLessonByKey(b.dataset.openLesson);return;}if(b.dataset.courseLesson!==undefined){current.lessonIndex=Number(b.dataset.courseLesson);render();return;}if(b.hasAttribute('data-complete')){const key=b.dataset.complete;if(!state.completed.includes(key)){state.completed.push(key);state.minutes+=5;save();toast('Lesson completed — great work!');}const l=lessonList.find(x=>x.key===key),next=l&&l.course.lessons[l.index+1];if(next){openLessonByKey(`${l.courseId}-${l.index+1}`);}else{render();toast('Course complete! Explore another course.');}return;}if(b.hasAttribute('data-prev-lesson')){if(current.lessonIndex>0){current.lessonIndex--;render();}return;}if(b.hasAttribute('data-check-quiz')){const key=b.dataset.checkQuiz,l=lessonList.find(x=>x.key===key),chosen=$('input[name="lessonAnswer"]:checked'),fb=$('#quizFeedback');if(!chosen){fb.textContent='Choose an answer first.';fb.style.color='var(--orange)';return;}const correct=Number(chosen.value)===l.quiz.correct;state.quizScores[key]={selected:Number(chosen.value),correct};save();fb.textContent=(correct?'Correct! ':'Not quite. ')+l.quiz.why;fb.style.color=correct?'var(--green)':'var(--orange)';return;}if(b.hasAttribute('data-copy-code')){copyText($('#lessonCode').textContent);return;}if(b.dataset.useExample){const l=lessonList.find(x=>x.key===b.dataset.useExample);go('playground');$('#playCode').value=exampleHtml(l);runCode();return;}if(b.dataset.bookmarkLesson){const l=lessonList.find(x=>x.key===b.dataset.bookmarkLesson);if(!state.bookmarks.some(x=>x.key===b.dataset.bookmarkLesson)){state.bookmarks.push({key:b.dataset.bookmarkLesson,title:`${l.courseTitle}: ${l.title}`,type:'Lesson'});save();toast('Lesson bookmarked');}else toast('Already bookmarked');return;}if(b.id==='runCode'){runCode();return;}if(b.id==='resetCode'){if($('#playCode'))$('#playCode').value=starterCode;runCode();return;}if(b.id==='mobileMenu'){$('#sidebar').classList.toggle('open');return;}if(b.hasAttribute('data-check-challenge')){checkChallenge(b.dataset.checkChallenge);return;}if(b.hasAttribute('data-hint')){const c=challenges.find(x=>x.id===b.dataset.hint);$('#feedback-'+c.id).textContent='Hint: '+c.hint;$('#feedback-'+c.id).style.color='var(--accent)';return;}if(b.hasAttribute('data-project')){const p=projects[Number(b.dataset.project)];$('#projectDetails').innerHTML=`<article class="panel" style="margin-top:18px"><div class="eyebrow">PROJECT CHECKLIST</div><h2 style="font:700 21px 'Space Grotesk'">${esc(p.title)}</h2><p>${esc(p.desc)}</p><p><strong>Starter guidance:</strong> ${esc(p.starter)}</p>${p.steps.map((s,i)=>`<label class="planner-row"><input type="checkbox"><div class="row-copy"><strong>Step ${i+1}</strong><small>${esc(s)}</small></div></label>`).join('')}<button class="button secondary" data-view="playground">Open code playground →</button></article>`;$('#projectDetails').scrollIntoView({behavior:'smooth',block:'start'});return;}if(b.hasAttribute('data-delete-note')){state.notes=state.notes.filter(n=>String(n.id)!==b.dataset.deleteNote);save();render();return;}if(b.hasAttribute('data-remove-bookmark')){state.bookmarks.splice(Number(b.dataset.removeBookmark),1);save();render();return;}if(b.hasAttribute('data-delete-task')){state.tasks=state.tasks.filter(t=>String(t.id)!==b.dataset.deleteTask);save();render();return;}if(b.id==='clearDone'){state.tasks=state.tasks.filter(t=>!t.done);save();render();return;}});
function exampleHtml(l){const escaped=l.code.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');return `<!doctype html><html><head><meta charset="utf-8"><style>body{font:16px Arial;padding:20px;color:#222}pre{white-space:pre-wrap;background:#f4f4f8;padding:12px;border-radius:8px}h1{color:#6558e8}</style></head><body><h1>Lesson code</h1><p>This playground runs HTML, CSS and JavaScript. This lesson's code may be a language example rather than a complete web page.</p><pre>${escaped}</pre></body></html>`;}
function checkChallenge(id){const c=challenges.find(x=>x.id===id),input=$('#answer-'+id),fb=$('#feedback-'+id);if(!c||!input||!fb)return;const ans=input.value.trim().toLowerCase().replace(/\s+/g,' ');const correct=c.answers.some(a=>ans===a.toLowerCase());if(correct&&!state.challenges.includes(id)){state.challenges.push(id);save();}fb.textContent=correct?`Correct! ${c.explain}`:'Not quite. Try again, or use the hint.';fb.style.color=correct?'var(--green)':'var(--orange)';const btn=$(`[data-check-challenge="${id}"]`);if(correct&&btn)btn.textContent='Completed ✓';}
document.addEventListener('submit',e=>{if(e.target.id==='noteForm'){e.preventDefault();const title=$('#noteTitle').value.trim(),body=$('#noteBody').value.trim();if(!title||!body)return;state.notes.push({id:Date.now(),title,body,created:Date.now()});save();render();toast('Note saved on this device');}if(e.target.id==='taskForm'){e.preventDefault();const title=$('#taskTitle').value.trim();if(!title)return;state.tasks.push({id:Date.now(),title,date:$('#taskDate').value,done:false});save();render();toast('Study task added');}});
document.addEventListener('change',e=>{if(e.target.dataset.taskToggle){const t=state.tasks.find(x=>String(x.id)===e.target.dataset.taskToggle);if(t)t.done=e.target.checked;save();render();}});
$('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){const q=e.target.value.trim().toLowerCase();if(!q){go('courses');return;}const found=lessonList.find(l=>(l.title+' '+l.courseTitle+' '+l.intro+' '+l.sections.map(s=>s.join(' ')).join(' ')).toLowerCase().includes(q));if(found){openLessonByKey(found.key);toast(`Found: ${found.title}`);}else{go('courses');const f=$('#courseSearch');if(f){f.value=q;f.dispatchEvent(new Event('input'));}toast('No lesson match. Filter the course list or try another term.');}}});$('#globalSearch').addEventListener('input',e=>{if(e.target.value.length>2&&current.view==='courses'){const f=$('#courseSearch');if(f){f.value=e.target.value;f.dispatchEvent(new Event('input'));}}});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch').focus();}if(e.key==='Escape')$('#sidebar').classList.remove('open');});
$('#themeToggle').addEventListener('click',()=>{document.body.classList.toggle('dark');state.theme=document.body.classList.contains('dark')?'dark':'light';save();});
$('#content').addEventListener('input',e=>{if(e.target.id==='courseSearch'){const q=e.target.value.toLowerCase(),lev=$('#levelFilter')?.value||'all';const list=courses.filter(c=>(c.title+' '+c.desc+' '+c.category+' '+c.lessons.map(l=>l.title).join(' ')).toLowerCase().includes(q)&&(lev==='all'||c.level===lev));$('#courseGrid').innerHTML=list.map(courseCard).join('')||'<div class="empty">No courses found. Try another word.</div>';}});$('#content').addEventListener('change',e=>{if(e.target.id==='levelFilter'){const f=$('#courseSearch');if(f)f.dispatchEvent(new Event('input'));}});
$('#authOpen').addEventListener('click',openAuth);$('#authClose').addEventListener('click',closeAuth);$('#authBackdrop').addEventListener('click',e=>{if(e.target.id==='authBackdrop')closeAuth();});$('#authForm').addEventListener('submit',submitAuth);$('#authModeToggle').addEventListener('click',()=>{authMode=authMode==='signin'?'signup':'signin';setAuthMessage('');updateAuthButton();});$('#authReset').addEventListener('click',async()=>{if(!supabaseClient){setAuthMessage('Configure Supabase first, then reload.',true);return;}const email=$('#authEmail').value.trim();if(!email){setAuthMessage('Enter your email address first.',true);return;}const {error}=await supabaseClient.auth.resetPasswordForEmail(email,{redirectTo:window.location.href.split('#')[0]});setAuthMessage(error?error.message:'If this email has an account, a password reset link will be sent. Open it on this site to choose a new password.');});$('#authSignOut').addEventListener('click',async()=>{if(!supabaseClient)return;const {error}=await supabaseClient.auth.signOut();if(error)setAuthMessage(error.message,true);else{closeAuth();toast('Signed out. Device copy remains available.');}});
if(state.theme==='dark')document.body.classList.add('dark');$('#courseCount').textContent=courses.length;render();initSupabase();
